import {validateMeaningState} from './meaning-engine.js';
export const GOALS=[{id:'cet4',label:'四级',detail:'官方大纲中的四级基础词目'},{id:'cet6',label:'六级',detail:'四级基础与六级增量词目'},{id:'ielts',label:'雅思',detail:'精编词库中的基础、学术与拓展用法'},{id:'all',label:'全词库',detail:'全部已收录的精编词条'}];
export function studyItem(lib,id){return Object.hasOwn(lib.studyItems||{},id)?lib.studyItems[id]:Object.hasOwn(lib.words,id)?lib.words[id]:undefined;}
export function canonicalId(id){return String(id).split('::')[0];}
export function goalLabel(s){return GOALS.find(g=>g.id===s.settings.goal)?.label||'全词库';}
export function targetMatch(w,goal='all'){if(!w)return false;if(goal==='all'||goal==='ielts')return true;return(w.targets||[]).includes(goal)||(goal==='cet6'&&(w.targets||[]).includes('cet4'));}
export function foundationSkipped(s,w){if(!w||w.isAdditionalSense||!s.settings.skipFoundation)return false;return s.settings.foundation==='cet4'?(w.targets||[]).includes('cet4'):s.settings.foundation==='cet6'?((w.targets||[]).includes('cet4')||(w.targets||[]).includes('cet6')):false;}
export function eligible(s,lib,id){const w=studyItem(lib,id);return !!w&&targetMatch(w,s.settings.goal)&&!foundationSkipped(s,w)&&s.words[id]?.status!=='known';}
export function newCandidates(s,lib,f){return(f.studyIds||f.wordIds).filter(id=>{const w=studyItem(lib,id);return eligible(s,lib,id)&&!s.words[id]&&(w.core||w.isAdditionalSense||s.settings.extended||s.settings.goal==='ielts');});}
export function visibleFamilyWords(s,lib,f,mode='target'){return f.wordIds.filter(id=>mode==='full'||targetMatch(lib.words[id],s.settings.goal)||(lib.words[id].studyItemIds||[]).some(x=>targetMatch(studyItem(lib,x),s.settings.goal)));}
export function wordStatus(s,lib,id,now=Date.now()){const w=lib.words[canonicalId(id)],ids=w?.studyItemIds||[id];if(ids.some(x=>eligible(s,lib,x)&&(s.words[x]?.due<=now||s.meanings?.[x]?.due<=now)))return'due';if(ids.some(x=>eligible(s,lib,x)&&(s.words[x]?.status==='review'||Object.hasOwn(s.meanings||{},x))))return'review';if(ids.some(x=>eligible(s,lib,x)&&!s.words[x]))return'new';if(s.words[id]?.status==='known'||foundationSkipped(s,w))return'known';return'outside';}
export function dueByFamily(s,lib,now=Date.now()){const preferred=s.days[dayKey(now)]?.family,groups=new Map();for(const id of dueWords(s,now,lib)){const w=studyItem(lib,id),fid=w.families?.includes(preferred)?preferred:w.families?.[0];if(!fid)continue;if(!groups.has(fid))groups.set(fid,{family:fid,ids:[]});groups.get(fid).ids.push(id);}return[...groups.values()];}
export function configureLearning(s,lib,settings,now=Date.now()){if(s.session||s.meaningSession?.queue.length)throw new Error('先完成当前练习，再切换学习目标。');const next={...s.settings,...settings};if(!GOALS.some(g=>g.id===next.goal)||!['none','cet4','cet6'].includes(next.foundation)||typeof next.skipFoundation!=='boolean'||typeof next.extended!=='boolean'||!['warm','plain'].includes(next.encouragement??'warm'))throw new Error('学习设置不正确。');s.settings=next;const d=ensureDay(s,lib,now);if(d.checked)return d;let f=lib.families.find(x=>x.id===d.family);if(!newCandidates(s,lib,f).length&&!d.newIds.some(id=>d.completed.includes(id)))f=lib.families.find(x=>newCandidates(s,lib,x).length)||f;d.family=f.id;const finishedNew=d.newIds.filter(id=>d.completed.includes(id)),desired=d.requestedTarget??next.target;d.newIds=[...new Set([...finishedNew,...newCandidates(s,lib,f).slice(0,Math.max(0,desired-finishedNew.length))])];d.target=d.newIds.length;d.reviewIds=[...new Set([...d.reviewIds.filter(id=>d.completed.includes(id)),...dueWords(s,now,lib)])];return d;}
export function markKnown(s,lib,id,now=Date.now()){if(!studyItem(lib,id))throw new Error('词条不存在。');if(s.session||s.meaningSession?.queue.length)throw new Error('请在本轮学习结束后调整掌握状态。');const old=s.words[id];if(old?.status==='known'){if(old.repetitions>0)s.words[id]={...old,status:'review',due:old.resumeDue||now};else delete s.words[id];}else{s.words[id]={...old,status:'known',resumeDue:old?.due||now,stage:old?.stage||0,due:0,first:old?.first||now,last:now,repetitions:old?.repetitions||0,lapses:old?.lapses||0};s.pending=s.pending.filter(x=>x!==id);}return configureLearning(s,lib,{},now);}
export const SCHEMA=1;
export function dayKey(now=Date.now()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(now));}
export function dayNumber(key){const [y,m,d]=key.split('-').map(Number);return Math.floor(Date.UTC(y,m-1,d)/86400000);}
export function freshState(){return {schema:SCHEMA,settings:{target:6,goal:'all',foundation:'none',skipFoundation:false,extended:false,encouragement:'warm'},words:{},knowledge:{},reading:{},meanings:{},meaningDays:{},meaningEvents:[],meaningSession:null,bookmarks:[],pending:[],days:{},session:null,events:[],updated:0};}
function validatePracticeSession(s,library){
  if(s.session===undefined||s.session===null)return;
  const ss=s.session,object=x=>!!x&&typeof x==='object'&&!Array.isArray(x),integer=x=>Number.isInteger(x)&&x>=0&&x<=1e6,stamp=x=>Number.isFinite(x)&&x>=0&&x<=8.64e15,token=x=>typeof x==='string'&&x.length>=12&&x.length<=80,fail=()=>{throw new Error('练习进度不正确。');};
  if(!object(ss)||!token(ss.id)||!['learn','review','pending','knowledge'].includes(ss.mode)||!stamp(ss.started)||!integer(ss.total)||ss.total>200||!Array.isArray(ss.queue)||ss.queue.length>200||!Array.isArray(ss.finished)||ss.finished.length>200)fail();
  const kind=ss.mode==='knowledge'?'knowledge':'word',valid=id=>typeof id==='string'&&(kind==='word'?!!studyItem(library,id):Object.hasOwn(library.cards,id));
  if(ss.finished.some(id=>!valid(id))||new Set(ss.finished).size!==ss.finished.length)fail();
  for(const q of ss.queue){
    if(!object(q)||q.kind!==kind||!valid(q.id)||!['study','question'].includes(q.phase)||!integer(q.streak)||!integer(q.attempts)||q.streak>q.attempts||typeof q.aided!=='boolean'||typeof q.failed!=='boolean'||typeof q.new!=='boolean')fail();
    if(q.family!==undefined&&q.family!==null&&(q.kind!=='word'||!library.families.some(f=>f.id===q.family&&(f.studyIds||f.wordIds).includes(q.id))))fail();
    // Old knowledge exports used the renderer's default when order was absent.
    if(q.kind==='knowledge'&&(q.optionOrder===undefined||q.optionOrder===null))q.optionOrder=[0,1,2,3];
    if(q.optionOrder!==undefined&&q.optionOrder!==null&&(!Array.isArray(q.optionOrder)||q.optionOrder.length!==4||new Set(q.optionOrder).size!==4||q.optionOrder.some(i=>!Number.isInteger(i)||i<0||i>3)))fail();
  }
  const queued=ss.queue.map(q=>q.id);
  if(new Set(queued).size!==queued.length||queued.some(id=>ss.finished.includes(id))||ss.total!==queued.length+ss.finished.length)fail();
  if(ss.feedback===undefined)ss.feedback=null;
  if(ss.feedback!==null){
    const fb=ss.feedback,q=ss.queue[0];
    if(!object(fb)||!q||q.phase!=='question'||fb.id!==q.id||typeof fb.correct!=='boolean'||typeof fb.done!=='boolean'||fb.done&&!fb.correct||!token(fb.event)||!stamp(fb.at)||!(typeof fb.attempt==='string'||Number.isFinite(fb.attempt)))fail();
  }
}
export function validateState(raw,library){if(!raw||raw.schema!==SCHEMA||!raw.words||!raw.knowledge||!raw.days||!Array.isArray(raw.bookmarks)||!Array.isArray(raw.pending)||!Array.isArray(raw.events))throw new Error('这份备份不是有效的学习记录。');const s=JSON.parse(JSON.stringify(raw));if(!Number.isInteger(s.settings?.target)||s.settings.target<0||s.settings.target>50)throw new Error('每日学习量不正确。');for(const [id,p]of Object.entries(s.words)){if(!studyItem(library,id)||!['learning','review','known'].includes(p.status)||!Number.isFinite(p.due)||!Number.isInteger(p.stage)||p.stage<0||p.stage>6)throw new Error('单词记录不正确。');}for(const [id,p]of Object.entries(s.knowledge)){if(!Object.hasOwn(library.cards,id)||!Number.isFinite(p.due)||!Number.isInteger(p.stage)||p.stage<0||p.stage>6)throw new Error('构词记录不正确。');}for(const [date,d]of Object.entries(s.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!library.families.some(f=>f.id===d.family)||!Array.isArray(d.newIds)||!Array.isArray(d.reviewIds)||!Array.isArray(d.completed)||!Array.isArray(d.learned)||!Array.isArray(d.recalled)||!Number.isInteger(d.target)||d.target<0||d.target>50||d.newIds.some(id=>!studyItem(library,id))||d.reviewIds.some(id=>!studyItem(library,id)))throw new Error('每日计划记录不正确。');}validatePracticeSession(s,library);if(s.bookmarks.some(id=>!studyItem(library,id))||s.pending.some(id=>!studyItem(library,id)))throw new Error('收藏记录不正确。');if(s.reading!==undefined&&(typeof s.reading!=='object'||s.reading===null||Array.isArray(s.reading)))throw new Error('刷词记录不正确。');s.reading??={};for(const [fid,p]of Object.entries(s.reading)){if(!library.families.some(f=>f.id===fid)||!p||typeof p.profile!=='string'||p.profile.length>128||typeof p.completed!=='boolean'||!Number.isFinite(p.updated)||!studyItem(library,p.cursor)||!Array.isArray(p.seenIds)||p.seenIds.length>400||new Set(p.seenIds).size!==p.seenIds.length||p.seenIds.some(id=>!studyItem(library,id)))throw new Error('刷词记录不正确。');}s.settings={goal:'all',foundation:'none',skipFoundation:false,extended:false,encouragement:'warm',...s.settings};if(!GOALS.some(g=>g.id===s.settings.goal)||!['none','cet4','cet6'].includes(s.settings.foundation)||typeof s.settings.skipFoundation!=='boolean'||typeof s.settings.extended!=='boolean'||!['warm','plain'].includes(s.settings.encouragement))throw new Error('学习目标不正确。');return validateMeaningState(s,library);}
export function dueWords(s,now=Date.now(),lib){return Object.keys(s.words).filter(id=>s.words[id].status!=='known'&&s.words[id].due<=now&&(!lib||eligible(s,lib,id))).sort((a,b)=>s.words[a].due-s.words[b].due);}
export function dueKnowledge(s,now=Date.now()){return Object.keys(s.knowledge).filter(id=>s.knowledge[id].due<=now).sort((a,b)=>s.knowledge[a].due-s.knowledge[b].due);}
export function ensureDay(s,lib,now=Date.now()){
  const k=dayKey(now);
  if(s.days[k]){
    const d=s.days[k];
    if(!d.checked&&!s.session){d.newIds=d.newIds.filter(id=>d.completed.includes(id)||eligible(s,lib,id));d.reviewIds=d.reviewIds.filter(id=>d.completed.includes(id)||eligible(s,lib,id));d.target=d.newIds.length;}
    if(!d.checked)for(const id of dueWords(s,now,lib))if(!d.completed.includes(id)&&!d.reviewIds.includes(id))d.reviewIds.push(id);
    return d;
  }
  const session=s.session,started=Number.isFinite(session?.started)?dayKey(session.started):null;
  const carry=started&&started!==k?session.queue.filter(q=>q.kind==='word'&&q.new&&eligible(s,lib,q.id)):[];
  const carryFamily=carry[0]?.family||studyItem(lib,carry[0]?.id)?.families?.[0];
  const resumedFamily=lib.families.find(f=>f.id===carryFamily);
  const viable=lib.families.filter(f=>newCandidates(s,lib,f).length),previous=Object.values(s.days).map(x=>x.family);
  const f=resumedFamily||viable.find(x=>!previous.includes(x.id))||viable[0]||lib.families[0],target=s.settings.target;
  const newIds=resumedFamily?[...new Set(carry.filter(q=>(q.family||studyItem(lib,q.id)?.families?.[0])===f.id).map(q=>q.id))].slice(0,50):newCandidates(s,lib,f).slice(0,target);
  return s.days[k]={family:f.id,target:newIds.length,requestedTarget:target,newIds,reviewIds:dueWords(s,now,lib),completed:[],learned:[],recalled:[],knowledge:[],checked:false,...(resumedFamily?{resumedFrom:started}:{})};
}
export function chooseFamily(s,lib,id,now=Date.now()){const d=ensureDay(s,lib,now);if(d.completed.length||s.session)throw new Error('今天已经开始学习，明天再切换主题。');const f=lib.families.find(f=>f.id===id);if(!f)throw new Error('词族不存在。');d.family=id;d.newIds=newCandidates(s,lib,f).slice(0,d.requestedTarget??d.target);d.target=d.newIds.length;return d;}
export function planProgress(d){const ids=[...new Set([...d.newIds,...d.reviewIds])];return {total:ids.length,done:ids.filter(x=>d.completed.includes(x)).length,newDone:d.newIds.filter(x=>d.completed.includes(x)).length,reviewDone:d.reviewIds.filter(x=>d.completed.includes(x)).length,ready:ids.length>0&&ids.every(x=>d.completed.includes(x))};}
function shuffled(){return [0,1,2,3].map(n=>({n,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.n);}
export function startSession(s,lib,mode,now=Date.now(),ids){if(s.session)return s.session;const d=ensureDay(s,lib,now);let chosen=ids;if(!chosen){if(mode==='learn')chosen=d.newIds.filter(x=>!d.completed.includes(x));else if(mode==='review')chosen=dueByFamily(s,lib,now).flatMap(g=>g.ids);else if(mode==='pending')chosen=s.pending.filter(x=>eligible(s,lib,x));else if(mode==='knowledge')chosen=dueKnowledge(s,now);}chosen=[...new Set(chosen||[])];const kind=mode==='knowledge'?'knowledge':'word';chosen=chosen.filter(id=>kind==='word'?eligible(s,lib,id):Object.hasOwn(lib.cards,id)).slice(0,100);if(!chosen.length)return null;const session={id:crypto.randomUUID(),mode,started:now,queue:chosen.map(id=>({id,kind,family:kind==='word'?(studyItem(lib,id).families?.includes(d.family)?d.family:studyItem(lib,id).families?.[0]):undefined,optionOrder:kind==='knowledge'?shuffled():null,phase:!s[kind==='word'?'words':'knowledge'][id]?'study':'question',streak:0,attempts:0,aided:false,failed:false,new:!s[kind==='word'?'words':'knowledge'][id]})),finished:[],total:chosen.length,feedback:null};s.session=session;return session;}
export function studyDone(s){const q=s.session?.queue[0];if(!q)throw new Error('没有正在进行的练习。');q.phase='question';}
export function aid(s){const q=s.session?.queue[0];if(q)q.aided=true;}
function addOnce(arr,id){if(!arr.includes(id))arr.push(id);}
export function answer(s,lib,value,now=Date.now()){const session=s.session,q=session?.queue[0];if(!q||q.phase!=='question'||session.feedback)return null;const obj=q.kind==='word'?studyItem(lib,q.id):lib.cards[q.id];const correct=q.kind==='word'?String(value).trim().toLowerCase()===obj.word.toLowerCase():Number(value)===obj.question.answer;q.attempts++;if(correct)q.streak++;else{q.streak=0;q.failed=true;}const done=correct&&(!q.new||q.streak>=2);session.feedback={correct,done,id:q.id,attempt:value,event:crypto.randomUUID(),at:now};return session.feedback;}
export function continueSession(s,lib,now=Date.now()){const session=s.session,fb=session?.feedback,q=session?.queue[0];if(!fb||!q)return false;const d=ensureDay(s,lib,now);session.queue.shift();if(!fb.done){q.phase='question';if(q.kind==='knowledge')q.optionOrder=shuffled();const boundary=q.family?session.queue.findIndex(x=>x.family!==q.family):-1;const index=Math.min(2,boundary<0?session.queue.length:boundary);session.queue.splice(index,0,q);if(!session.queue.length)session.queue.push(q);}else{const box=q.kind==='word'?'words':'knowledge';const old=s[box][q.id];const stage=(q.failed||q.aided)?0:Math.min((old?.stage??-1)+1,5);const intervals=[1,3,7,14,30,60];s[box][q.id]={status:'review',stage,due:now+intervals[stage]*86400000,first:old?.first??now,last:now,lapses:(old?.lapses||0)+(q.failed?1:0),aided:q.aided,repetitions:(old?.repetitions||0)+1};if(q.kind==='word'){addOnce(d.completed,q.id);if(q.new)addOnce(d.learned,q.id);else addOnce(d.recalled,q.id);s.pending=s.pending.filter(x=>x!==q.id);}else addOnce(d.knowledge,q.id);addOnce(session.finished,q.id);}s.events.push({id:fb.event,kind:q.kind,item:q.id,correct:fb.correct,aided:q.aided,at:fb.at});s.events=s.events.slice(-2000);session.feedback=null;return true;}
export function finishSession(s){const x=s.session;if(!x||x.queue.length)throw new Error('练习尚未完成。');s.session=null;return x;}
export function skipKnown(s,lib,now=Date.now()){if(s.meaningSession?.queue.length)throw new Error('先完成本轮词义回忆，再调整已认识状态。');const session=s.session,q=session?.queue[0];if(!q||q.kind!=='word'||!q.new||q.phase!=='study')throw new Error('只能在首次学习时跳过已认识的词。');const d=ensureDay(s,lib,now);s.words[q.id]={status:'known',stage:0,due:0,first:now,last:now,repetitions:0,lapses:0};session.queue.shift();s.pending=s.pending.filter(id=>id!==q.id);if(d.newIds.includes(q.id)){d.newIds=d.newIds.filter(id=>id!==q.id);const f=lib.families.find(f=>f.id===d.family);const extra=newCandidates(s,lib,f).find(id=>!d.newIds.includes(id));if(extra){d.newIds.push(extra);if(!session.queue.some(x=>x.id===extra))session.queue.push({id:extra,kind:'word',family:f.id,phase:'study',streak:0,attempts:0,aided:false,failed:false,new:true});else session.total--;}else{d.target=d.newIds.length;session.total--;}}else session.total--;return q.id;}
export function checkIn(s,lib,now=Date.now()){const d=ensureDay(s,lib,now),p=planProgress(d);if(!p.ready)throw new Error('完成今天的新词与计划复习后，就可以打卡。');d.checked=true;return dayKey(now);}
export function stats(s,now=Date.now()){const dates=[...new Set([...Object.keys(s.days).filter(k=>s.days[k].checked),...Object.keys(s.meaningDays||{}).filter(k=>s.meaningDays[k].checked)])].sort();let n=dayNumber(dayKey(now));if(!dates.includes(dayKey(now)))n--;const set=new Set(dates.map(dayNumber));let streak=0;while(set.has(n)){streak++;n--;}return {learned:new Set(Object.entries(s.words).filter(([,x])=>x.status==='review'||x.repetitions>0).map(([id])=>canonicalId(id))).size,known:new Set(Object.entries(s.words).filter(([,x])=>x.status==='known').map(([id])=>canonicalId(id))).size,senses:Object.keys(s.words).filter(id=>id.includes('::')).length,knowledge:Object.keys(s.knowledge).length,totalDays:dates.length,streak};}
